 89 |   function syncGlobalCollateral() public onlyActive {
 90 |     globalIC.sync(getCollateralizedMalt());
 91 |   }
 92 | 
 93 |   function getCollateralizedMalt() public view returns (PoolCollateral memory) {
 94 |     uint256 target = maltDataLab.priceTarget();
 95 | 
 96 |     uint256 unity = 10**collateralToken.decimals();
 97 | 
 98 |     // Convert all balances to be denominated in units of Malt target price
 99 |     uint256 overflowBalance = maltDataLab.rewardToMaltDecimals((collateralToken.balanceOf(
100 |       address(overflowPool)
101 |     ) * unity) / target);
102 |     uint256 liquidityExtensionBalance = (collateralToken.balanceOf(
103 |       address(liquidityExtension)
104 |     ) * unity) / target;
105 |     (
106 |       uint256 swingTraderMaltBalance,
107 |       uint256 swingTraderBalance
108 |     ) = swingTraderManager.getTokenBalances();
109 |     swingTraderBalance = (swingTraderBalance * unity) / target;
110 | 
111 |     return
112 |       PoolCollateral({
113 |         lpPool: address(stakeToken),
114 |         // Note that swingTraderBalance also includes the overflowBalance
115 |         // Therefore the total doesn't need to include overflowBalance explicitly
116 |         total: maltDataLab.rewardToMaltDecimals(
117 |             liquidityExtensionBalance + swingTraderBalance
118 |         ),
119 |         rewardOverflow: overflowBalance,
120 |         liquidityExtension: maltDataLab.rewardToMaltDecimals(
121 |           liquidityExtensionBalance
122 |         ),
123 |         // This swingTraderBalance value isn't just the capital in the swingTrader
124 |         // contract but also includes what is in the overflow so we subtract that
125 |         swingTrader: maltDataLab.rewardToMaltDecimals(swingTraderBalance) - overflowBalance,
126 |         swingTraderMalt: swingTraderMaltBalance,
127 |         arbTokens: maltDataLab.rewardToMaltDecimals(
128 |           auction.unclaimedArbTokens()
129 |         )

30 | /// @notice The backbone of the Malt stability system. In charge of triggering actions to stabilize price
31 | contract StabilizerNode is
32 |   StabilizedPoolUnit,
33 |   AuctionExtension,
34 |   DexHandlerExtension,
35 |   DataLabExtension,
36 |   ProfitDistributorExtension,
37 |   SwingTraderManagerExtension,
38 |   ImpliedCollateralServiceExtension,
39 |   Pausable
40 | {
41 |   using SafeERC20 for ERC20;
42 | 
43 |   uint256 internal stabilizeWindowEnd;
44 |   uint256 public stabilizeBackoffPeriod = 5 * 60; // 5 minutes
45 |   uint256 public upperStabilityThresholdBps = 100; // 1%
46 |   uint256 public lowerStabilityThresholdBps = 100;
47 |   uint256 public priceAveragePeriod = 5 minutes;
48 |   uint256 public fastAveragePeriod = 30; // 30 seconds
49 |   uint256 public overrideDistanceBps = 200; // 2%
50 |   uint256 public callerRewardCutBps = 30; // 0.3%
51 | 
52 |   uint256 public expansionDampingFactor = 1;
53 | 
54 |   uint256 public defaultIncentive = 100; // in Malt
55 |   uint256 public trackingIncentive = 20; // in 100ths of a Malt
56 | 
57 |   uint256 public upperBandLimitBps = 100000; // 1000%
58 |   uint256 public lowerBandLimitBps = 1000; // 10%
59 |   uint256 public sampleSlippageBps = 2000; // 20%
60 |   uint256 public skipAuctionThreshold;
61 |   uint256 public preferAuctionThreshold;
62 | 
63 |   uint256 public lastStabilize;
64 |   uint256 public lastTracking;
65 |   uint256 public trackingBackoff = 30; // 30 seconds
66 |   uint256 public primedBlock;
67 |   uint256 public primedWindow = 10; // blocks
68 | 
69 |   bool internal trackAfterStabilize = true;
70 |   bool public onlyStabilizeToPeg = false;
71 |   bool public usePrimedWindow;
72 | 
73 |   address public supplyDistributionController;
74 |   address public auctionStartController;
75 | 
76 |   event MintMalt(uint256 amount);
77 |   event Stabilize(uint256 timestamp, uint256 exchangeRate);
78 |   event SetStabilizeBackoff(uint256 period);
79 |   event SetDefaultIncentive(uint256 incentive);
80 |   event SetTrackingIncentive(uint256 incentive);
81 |   event SetExpansionDamping(uint256 amount);
82 |   event SetPriceAveragePeriod(uint256 period);
83 |   event SetOverrideDistance(uint256 distance);
84 |   event SetFastAveragePeriod(uint256 period);
85 |   event SetStabilityThresholds(uint256 upper, uint256 lower);
86 |   event SetSupplyDistributionController(address _controller);
87 |   event SetAuctionStartController(address _controller);
88 |   event SetBandLimits(uint256 _upper, uint256 _lower);
89 |   event SetSlippageBps(uint256 _slippageBps);
90 |   event SetSkipAuctionThreshold(uint256 _skipAuctionThreshold);
